// Compare the bounds by value so new objects with the same time don't re-validate
const minimumTimeKey = JSON.stringify(minimumTime);
const maximumTimeKey = JSON.stringify(maximumTime);

// Effect Events read the latest time and bounds without re-running the effects
const revalidateTime = useEffectEvent(() => {
  validate(time);
});
const validateDefaultTime = useEffectEvent((newDefaultTime: Time) => {
  validate(newDefaultTime);
});

useEffect(() => {
  if (minimumTimeKey || maximumTimeKey) {
    revalidateTime();
  }
}, [minimumTimeKey, maximumTimeKey]);

useEffect(() => {
  if (defaultTime) {
    setTime(defaultTime);
    validateDefaultTime(defaultTime);
  }
}, [defaultTime]);
